% Reference caller body for templateId plots. The worker owns the preamble.
\begin{tikzpicture}
\begin{axis}[width=0.9\linewidth, height=6cm,
    xlabel={時間 Time (\si{\second})},
    ylabel={電壓 Voltage (\si{\volt})},
    grid=major, legend pos=north west, title={充電曲線 Charging}]
